import{_ as s,o as t,c as e,a0 as i}from"./chunks/framework.DQOulFGV.js";const k=JSON.parse('{"title":"把 Mac 备份到 NAS","description":"用 Keelhaven 把 Mac 加密、定时备份到群晖、威联通或任何一台 NAS：在访达里挂载共享文件夹，或者用 SSH 密钥走 SFTP。","frontmatter":{"title":"把 Mac 备份到 NAS","description":"用 Keelhaven 把 Mac 加密、定时备份到群晖、威联通或任何一台 NAS：在访达里挂载共享文件夹，或者用 SSH 密钥走 SFTP。"},"headers":[],"relativePath":"zh/guides/nas.md","filePath":"zh/guides/nas.md"}'),n={name:"zh/guides/nas.md"};function o(l,a,r,h,d,p){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="把-mac-备份到-nas" tabindex="-1">把 Mac 备份到 NAS <a class="header-anchor" href="#把-mac-备份到-nas" aria-label="Permalink to &quot;把 Mac 备份到 NAS&quot;">​</a></h1><p>Keelhaven 先在你的 Mac 上把选中的文件夹加密，再存到 NAS 上。别人在 NAS 上 打开那个目录，看到的只有加密数据。</p><p>连 NAS 有两种办法。没用过 SSH 密钥的话，从第一种开始。</p><h2 id="简单的办法-挂载共享文件夹" tabindex="-1">简单的办法：挂载共享文件夹 <a class="header-anchor" href="#简单的办法-挂载共享文件夹" aria-label="Permalink to &quot;简单的办法：挂载共享文件夹&quot;">​</a></h2><ol><li>在访达里选<strong>前往 → 连接服务器…</strong>，输入 <code>smb://</code> 加 NAS 的名字，比如 <code>smb://nas.local</code>，然后打开用来放备份的共享文件夹。</li><li>在 Keelhaven 里点菜单栏的灯塔图标，选<strong>添加备份计划…</strong>，挑好文件夹。</li><li>到下一步，点<strong>选取…</strong>，选共享文件夹里的一个目录。它在边栏的<strong>位置</strong>下面。</li><li>设好加密密码和备份频率。</li></ol><p>备份运行时，共享文件夹必须处于挂载状态。没挂载的话，那一次会失败， Keelhaven 会告诉你。数据不会丢：下一次会把上次成功之后的变化都补上。</p><h2 id="不想挂载-走-sftp" tabindex="-1">不想挂载：走 SFTP <a class="header-anchor" href="#不想挂载-走-sftp" aria-label="Permalink to &quot;不想挂载：走 SFTP&quot;">​</a></h2><p>走 SFTP 的话，只要 NAS 在网络上，Keelhaven 自己就能连上。它用 SSH 密钥登录， 从不询问 NAS 的密码，所以得先保证密钥登录是通的。</p><p><strong>1. 先在终端里试一下。</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup@nas.local</span></span></code></pre></div><p>这条命令必须不问密码、也不问密钥口令就能登进去。第一次连接时它会问是否 信任这台 NAS，在这里回答 yes，因为这个问题 Keelhaven 没法替你回答。</p><p>如果它问了密码，说明 NAS 上还没有你的公钥：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 还没有密钥时才需要</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup@nas.local</span></span></code></pre></div><p><strong>2. 接入 Keelhaven。</strong> 在选目的地那一步展开<strong>高级选项</strong>，选 <strong>SFTP / NAS</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>用户名</td><td>NAS 上的账号，比如 <code>backup</code></td></tr><tr><td>主机</td><td><code>nas.local</code>，或者它的 IP 地址</td></tr><tr><td>端口</td><td><code>22</code>，除非你改过</td></tr><tr><td>服务器上的路径</td><td>放这台 Mac 备份的目录，比如 <code>/backups/mac</code></td></tr></tbody></table><p>然后同样是加密密码和备份频率。</p><h3 id="群晖上要注意" tabindex="-1">群晖上要注意 <a class="header-anchor" href="#群晖上要注意" aria-label="Permalink to &quot;群晖上要注意&quot;">​</a></h3><ul><li>SFTP 默认是关的：<strong>控制面板 → 文件服务 → FTP → 启动 SFTP 服务</strong>。</li><li>密钥登录需要有个人文件夹来放公钥：<strong>控制面板 → 用户与群组 → 高级设置 → 启动家目录服务</strong>。剩下的步骤看群晖的 <a href="https://kb.synology.com/en-uk/DSM/tutorial/How_to_log_in_to_DSM_with_key_pairs_as_admin_or_root_permission_via_SSH_on_computers" target="_blank" rel="noreferrer">密钥登录教程</a>。</li><li>走 SFTP 时，群晖通常把共享文件夹直接列在最上层，所以路径是 <code>/backups/mac</code>，而不是 <code>/volume1/backups/mac</code>。运行 <code>sftp backup@nas.local</code> 再输入 <code>ls</code>，就能看到你那台显示的是什么。</li></ul><h2 id="值得知道" tabindex="-1">值得知道 <a class="header-anchor" href="#值得知道" aria-label="Permalink to &quot;值得知道&quot;">​</a></h2><p><strong>放在同一个家里的 NAS 只算一份，不算两份。</strong> 它防的是 Mac 坏掉，防不了 火灾和入室盗窃。再建一个计划备份到<a href="/zh/guides/backblaze-b2">存储桶</a>就能 补上，<strong>复制计划…</strong> 可以把现有计划拷到新的目的地。</p><p><strong>不装 Keelhaven 也能恢复。</strong> 那个目录里是标准的 <a href="https://restic.net" target="_blank" rel="noreferrer">restic</a> 仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sftp:backup@nas.local:/backups/mac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshots</span></span></code></pre></div>`,22)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
